#!/usr/bin/env python3
"""Lossless, self-contained corpus compressor (standard library only)."""
import bz2
import sys
from pathlib import Path


def compress(data):
    return bz2.compress(data, compresslevel=9)


def decompress(data):
    return bz2.decompress(data)


def main():
    args = sys.argv[1:]
    decode = bool(args and args[0] == '--decompress')
    if decode:
        args = args[1:]
    if len(args) != 2:
        raise SystemExit('usage: compress.py [--decompress] INPUT OUTPUT')
    data = Path(args[0]).read_bytes()
    Path(args[1]).write_bytes(decompress(data) if decode else compress(data))


if __name__ == '__main__':
    main()

"""Correctness-gated size score; repeats work for at least 0.4 seconds."""
import time
import zlib
from pathlib import Path
import compress


def score():
    original = Path('corpus.txt').read_bytes()
    deadline = time.perf_counter() + 0.4
    first = None
    while True:
        packed = compress.compress(original)
        if compress.decompress(packed) != original:
            return 0.0
        if first is None:
            first = packed
        elif packed != first:
            return 0.0
        if time.perf_counter() >= deadline:
            break
    Path('out.bin').write_bytes(first)
    if len(first) >= len(zlib.compress(original)):
        return 0.0
    return 100.0 * (1.0 - len(first) / len(original))


try:
    print(score())
except Exception:
    print(0.0)

