import bz2
import collections
import json
import re
import struct
import sys
import zlib
from pathlib import Path


def pack_digits(values, base):
    value = 0
    for digit in values:
        value = value * base + digit
    return value.to_bytes((value.bit_length() + 7) // 8, 'big')


def unpack_digits(data, base, count):
    value = int.from_bytes(data, 'big')
    out = [0] * count
    for i in range(count - 1, -1, -1):
        value, out[i] = divmod(value, base)
    if value:
        raise ValueError('invalid digit stream')
    return out


def compress(data):
    lines = data.splitlines(keepends=True)
    records = []
    fallback = lambda: b'BZ1' + bz2.compress(data, 9)
    if len(lines) < 6:
        return fallback()
    for i, line in enumerate(lines):
        m = re.fullmatch(rb'(\d+) (.*) (\d+)\n', line)
        if m is None or m[1] != ('%05d' % i).encode():
            return fallback()
        records.append((m[2], int(m[3])))
    modulus = max(n for _, n in records) + 1
    step = records[1][1]
    if any(n != i * step % modulus for i, (_, n) in enumerate(records)):
        return fallback()
    templates = [collections.Counter(s for s, _ in records[k::6]).most_common(1)[0][0] for k in range(6)]
    vocab = sorted({w for i, (s, _) in enumerate(records) if s != templates[i % 6] for w in s.split(b' ')})
    ids = {w: i for i, w in enumerate(vocab)}
    lengths, words = [], []
    for i, (text, _) in enumerate(records):
        tokens = [] if text == templates[i % 6] else [ids[w] for w in text.split(b' ')]
        lengths.append(len(tokens))
        words.extend(tokens)
    nonzero = [n for n in lengths if n]
    low, high = (min(nonzero), max(nonzero)) if nonzero else (1, 1)
    flags = bytes(sum(bool(v) << j for j, v in enumerate(lengths[i:i+8])) for i in range(0, len(lines), 8))
    flags = zlib.compress(flags, 9)
    lens = pack_digits((n - low for n in nonzero), high - low + 1)
    wordstream = pack_digits(words, max(1, len(vocab)))
    meta = [len(lines), step, modulus, [s.decode('latin1') for s in templates], [s.decode('latin1') for s in vocab], low, high]
    header = zlib.compress(json.dumps(meta, ensure_ascii=True, separators=(',', ':')).encode(), 9)
    archive = b'CP1' + struct.pack('<III', len(header), len(flags), len(lens)) + header + flags + lens + wordstream
    return archive if decompress(archive) == data else fallback()


